#[derive(Default)]
struct PhysicalIoCounters {
    ranges: AtomicU64,
    bytes: AtomicU64,
    nowait_attempts: AtomicU64,
    nowait_hits: AtomicU64,
    nowait_misses: AtomicU64,
    nowait_unsupported: AtomicU64,
    occupancy: Mutex<PhysicalIoOccupancy>,
}

#[derive(Default)]
struct PhysicalIoOccupancy {
    capacity: usize,
    active: usize,
    max_active: usize,
    first: Option<Instant>,
    last: Option<Instant>,
    full: Duration,
    underfilled: Duration,
    idle: Duration,
    refill_wait: Duration,
    not_full_since_last_submit: Duration,
    active_slot_nanos: u128,
}

impl PhysicalIoCounters {
    fn submit(&self, count: usize, capacity: usize) {
        let mut occupancy = self.occupancy.lock();
        occupancy.advance(Instant::now());
        let refill_wait = occupancy.not_full_since_last_submit;
        occupancy.refill_wait += refill_wait;
        occupancy.not_full_since_last_submit = Duration::ZERO;
        occupancy.capacity = capacity;
        occupancy.active = occupancy.active.saturating_add(count);
        occupancy.max_active = occupancy.max_active.max(occupancy.active);
    }

    fn complete(&self) {
        let mut occupancy = self.occupancy.lock();
        occupancy.advance(Instant::now());
        occupancy.active = occupancy.active.saturating_sub(1);
    }

    fn occupancy(&self) -> SourceIoOccupancy {
        let occupancy = self.occupancy.lock();
        SourceIoOccupancy {
            capacity: occupancy.capacity,
            max_active: occupancy.max_active,
            span: occupancy
                .first
                .zip(occupancy.last)
                .map(|(first, last)| last.duration_since(first))
                .unwrap_or_default(),
            full: occupancy.full,
            underfilled: occupancy.underfilled,
            idle: occupancy.idle,
            refill_wait: occupancy.refill_wait,
            tail_drain: occupancy.not_full_since_last_submit,
            active_slot_nanos: occupancy.active_slot_nanos,
        }
    }
}

impl PhysicalIoOccupancy {
    fn advance(&mut self, now: Instant) {
        let Some(last) = self.last.replace(now) else {
            self.first = Some(now);
            return;
        };
        let elapsed = now.duration_since(last);
        self.active_slot_nanos = self
            .active_slot_nanos
            .saturating_add(elapsed.as_nanos().saturating_mul(self.active as u128));
        if self.active == 0 {
            self.idle += elapsed;
            self.not_full_since_last_submit += elapsed;
        } else if self.active >= self.capacity {
            self.full += elapsed;
        } else {
            self.underfilled += elapsed;
            self.not_full_since_last_submit += elapsed;
        }
    }
}

#[derive(Clone)]
struct CountingReadAt {
    inner: Arc<dyn VortexReadAt>,
    inline_reader: Option<Arc<FileReadAt>>,
    inline_max_bytes: Option<usize>,
    latency: Duration,
    counters: Arc<PhysicalIoCounters>,
    coalesce_override: Option<CoalesceConfig>,
    concurrency_override: Option<usize>,
}

impl VortexReadAt for CountingReadAt {
    fn uri(&self) -> Option<&Arc<str>> {
        self.inner.uri()
    }

    fn coalesce_config(&self) -> Option<CoalesceConfig> {
        self.coalesce_override
            .or_else(|| self.inner.coalesce_config())
    }

    fn concurrency(&self) -> usize {
        self.concurrency_override
            .unwrap_or_else(|| self.inner.concurrency())
    }

    fn size(&self) -> BoxFuture<'static, VortexResult<u64>> {
        self.inner.size()
    }

    fn read_at(
        &self,
        offset: u64,
        length: usize,
        alignment: Alignment,
    ) -> BoxFuture<'static, VortexResult<BufferHandle>> {
        self.counters.ranges.fetch_add(1, Ordering::Relaxed);
        self.counters
            .bytes
            .fetch_add(length as u64, Ordering::Relaxed);
        let read = self.inner.read_at(offset, length, alignment);
        let counters = Arc::clone(&self.counters);
        let capacity = self.concurrency();
        let latency = self.latency;
        Box::pin(async move {
            counters.submit(1, capacity);
            if !latency.is_zero() {
                tokio::time::sleep(latency).await;
            }
            let result = read.await;
            counters.complete();
            result
        })
    }

    fn read_ranges(&self, requests: Arc<[ReadAtRequest]>) -> ReadAtStream {
        self.counters
            .ranges
            .fetch_add(requests.len() as u64, Ordering::Relaxed);
        self.counters.bytes.fetch_add(
            requests.iter().map(|request| request.length as u64).sum(),
            Ordering::Relaxed,
        );
        let capacity = self.concurrency();
        let inner = Arc::clone(&self.inner);
        let counters = Arc::clone(&self.counters);
        let latency = self.latency;
        let reads = requests
            .iter()
            .copied()
            .map(move |request| {
                let read = inner.read_at(request.offset, request.length, request.alignment);
                let counters = Arc::clone(&counters);
                async move {
                    counters.submit(1, capacity);
                    if !latency.is_zero() {
                        tokio::time::sleep(latency).await;
                    }
                    let result = read.await;
                    counters.complete();
                    (request, result)
                }
            })
            .collect::<Vec<_>>();
        futures::stream::iter(reads)
            .buffer_unordered(capacity)
            .boxed()
    }

    fn read_at_nowait(
        &self,
        offset: u64,
        length: usize,
        alignment: Alignment,
    ) -> VortexResult<ReadAtNowait> {
        self.counters
            .nowait_attempts
            .fetch_add(1, Ordering::Relaxed);
        let result = match (self.inline_max_bytes, self.inline_reader.as_ref()) {
            (Some(max_bytes), Some(reader)) if length <= max_bytes => {
                ReadAtNowait::Ready(reader.read_at_inline(offset, length, alignment)?)
            }
            (Some(_), Some(_)) => ReadAtNowait::WouldBlock,
            _ => self.inner.read_at_nowait(offset, length, alignment)?,
        };
        match &result {
            ReadAtNowait::Ready(_) => {
                self.counters.nowait_hits.fetch_add(1, Ordering::Relaxed);
                self.counters.ranges.fetch_add(1, Ordering::Relaxed);
                self.counters
                    .bytes
                    .fetch_add(length as u64, Ordering::Relaxed);
            }
            ReadAtNowait::WouldBlock => {
                self.counters.nowait_misses.fetch_add(1, Ordering::Relaxed);
            }
            ReadAtNowait::Unsupported => {
                self.counters
                    .nowait_unsupported
                    .fetch_add(1, Ordering::Relaxed);
            }
        }
        Ok(result)
    }
}

struct DiskBackend {
    path: PathBuf,
    specs: Arc<[SegmentSpec]>,
    runtime: Handle,
    reused_pack: bool,
    evict_before_run: bool,
    coalesce_override: Option<CoalesceConfig>,
    io_depth: Option<usize>,
    inline_max_bytes: Option<usize>,
    io_latency: Duration,
}

enum SegmentBackend {
    Memory(Arc<dyn SegmentSource>),
    Disk(DiskBackend),
}

type MeasuredSegmentSource = (Arc<dyn SegmentSource>, Option<Arc<PhysicalIoCounters>>);

impl SegmentBackend {
    fn source(&self, session: &VortexSession) -> VortexResult<MeasuredSegmentSource> {
        match self {
            Self::Memory(source) => Ok((Arc::clone(source), None)),
            Self::Disk(disk) => {
                if disk.evict_before_run {
                    #[cfg(not(target_vendor = "apple"))]
                    {
                        let file = File::open(&disk.path)?;
                        fadvise(&file, 0, None, Advice::DontNeed).map_err(|err| {
                            vortex_error::vortex_err!(
                                "failed to evict {}: {err}",
                                disk.path.display()
                            )
                        })?;
                        drop(file);
                    }
                }

                let read = Arc::new(FileReadAt::open(&disk.path, session.handle())?);
                #[cfg(target_vendor = "apple")]
                if disk.evict_before_run {
                    read.set_nocache(true)?;
                }
                let inline_reader = disk.inline_max_bytes.map(|_| Arc::clone(&read));
                let read: Arc<dyn VortexReadAt> = read;
                let counters = Arc::new(PhysicalIoCounters::default());
                let read = CountingReadAt {
                    inner: read,
                    inline_reader,
                    inline_max_bytes: disk.inline_max_bytes,
                    latency: disk.io_latency,
                    counters: Arc::clone(&counters),
                    coalesce_override: disk.coalesce_override,
                    concurrency_override: disk.io_depth,
                };
                let metrics = DefaultMetricsRegistry::default();
                let source = FileSegmentSource::open(
                    Arc::clone(&disk.specs),
                    read,
                    session.handle(),
                    RequestMetrics::new(&metrics, vec![]),
                );
                let source: Arc<dyn SegmentSource> = Arc::new(SharedSegmentSource::new(source));
                Ok((source, Some(counters)))
            }
        }
    }
}

fn write_segment_pack(
    path: &Path,
    buffers: &[ByteBuffer],
    _uncached: bool,
) -> VortexResult<Arc<[SegmentSpec]>> {
    let (specs, _) = segment_pack_specs(buffers)?;
    let mut file = File::create(path)?;
    #[cfg(target_vendor = "apple")]
    if _uncached {
        rustix::fs::fcntl_nocache(&file, true).map_err(std::io::Error::from)?;
    }
    for (buffer, spec) in buffers.iter().zip(specs.iter()) {
        if spec.offset > file.stream_position()? {
            file.seek(SeekFrom::Start(spec.offset))?;
        }
        file.write_all(buffer.as_ref())?;
    }
    file.sync_all()?;
    Ok(specs)
}

fn segment_pack_specs(buffers: &[ByteBuffer]) -> VortexResult<(Arc<[SegmentSpec]>, u64)> {
    let mut offset = 0u64;
    let mut specs = Vec::with_capacity(buffers.len());
    for buffer in buffers {
        let alignment = buffer.alignment();
        let aligned = offset.next_multiple_of(*alignment as u64);
        let length = u32::try_from(buffer.len())
            .map_err(|_| vortex_error::vortex_err!("segment exceeds u32 length"))?;
        specs.push(SegmentSpec {
            offset: aligned,
            length,
            alignment,
        });
        offset = aligned + u64::from(length);
    }
    Ok((specs.into(), offset))
}

fn reuse_segment_pack(path: &Path, buffers: &[ByteBuffer]) -> VortexResult<Arc<[SegmentSpec]>> {
    let (specs, expected_len) = segment_pack_specs(buffers)?;
    let mut file = File::open(path)?;
    vortex_ensure!(
        file.metadata()?.len() == expected_len,
        "existing segment pack {} has the wrong length",
        path.display()
    );
    if buffers.is_empty() {
        return Ok(specs);
    }
    let mut sample_indices = vec![0, buffers.len() / 2, buffers.len() - 1];
    sample_indices.sort_unstable();
    sample_indices.dedup();
    for index in sample_indices {
        let spec = specs[index];
        let mut actual = vec![0; spec.length as usize];
        file.seek(SeekFrom::Start(spec.offset))?;
        file.read_exact(&mut actual)?;
        vortex_ensure!(
            actual == buffers[index].as_ref(),
            "existing segment pack {} does not match generated segment {index}",
            path.display()
        );
    }
    Ok(specs)
}

fn main() -> VortexResult<()> {
    // The full session: every encoding plugin registered, so the compressing writer can
    // serialise what btrblocks produces and the readers can decode it.
    let session = VortexSession::default();
    let threads = std::env::var("TPCH_THREADS")
        .ok()
        .map(|value| {
            value
                .parse::<usize>()
                .map_err(|err| vortex_error::vortex_err!("invalid TPCH_THREADS: {err}"))
        })
        .transpose()?
        .unwrap_or_else(|| get_available_parallelism().unwrap_or(4))
        .max(1);
    let iterations: usize = std::env::var("TPCH_ITERATIONS")
        .ok()
        .and_then(|v| v.parse().ok())
        .unwrap_or(DEFAULT_ITERATIONS)
        .max(1);
    let runtime = tokio::runtime::Builder::new_multi_thread()
        .worker_threads(threads)
        .enable_all()
        .build()
        .map_err(|err| vortex_error::vortex_err!("failed to build the tokio runtime: {err}"))?;
    let scale: f64 = std::env::args()
        .nth(1)
        .and_then(|arg| arg.parse().ok())
        .or_else(|| {
            std::env::var("TPCH_SCALE")
                .ok()
                .and_then(|v| v.parse().ok())
        })
        .unwrap_or(0.5);
    let row_block: usize = std::env::var("TPCH_ROW_BLOCK")
        .ok()
        .and_then(|v| v.parse().ok())
        .unwrap_or(8192);
    // The production default block target. Lowering it produces more, smaller chunks, which is
    // the knob that decides how many morsels a scan is cut into.
    let block_target: u64 = std::env::var("TPCH_BLOCK_BYTES")
        .ok()
        .and_then(|v| v.parse().ok())
        .unwrap_or(1 << 20);

    println!("# TPC-H scan evaluation: V1 LayoutReader vs the morsel executor");
    println!();

    // 1. Generate real lineitem.
    let gen_start = Instant::now();
    let table = tpch::lineitem(&session, scale, 65_536)?;
    let gen_elapsed = gen_start.elapsed();

    // 2. Write it through the real compressing pipeline.
    let strategy = tpch::write_strategy(row_block, block_target);
    let write_start = Instant::now();
    let columns = tpch::columns(&table, 0, &session)?;
    let ncolumns = columns.len();
    let generated_rows = table.row_count;
    // The generated struct batches are no longer needed once split into columns.
    drop(table);
    // The compressing pipeline spawns CPU work, so the writing session needs a runtime handle.
    let mut fixture = {
        let session = session.clone();
        block_on(move |handle| {
            let session = session.with_handle(handle);
            async move { write_streaming_fixture_no_table(columns, strategy, &session).await }
        })?
    };
    // `VortexSession` clones share their extension registry, so the single-thread fixture writer
    // above temporarily replaces the runtime handle for every clone. Install the persistent Tokio
    // executor only after the writer has finished.
    let io_executor: Arc<dyn Executor> = Arc::new(runtime.handle().clone());
    let session = session.with_handle(Handle::new(Arc::downgrade(&io_executor)));
    let write_elapsed = write_start.elapsed();
    let segments: Arc<dyn SegmentSource> = Arc::clone(&fixture.segments);
    let disk_path = std::env::var_os("TPCH_DISK_PATH").map(PathBuf::from);
    let reuse_disk_pack = std::env::var("TPCH_REUSE_DISK_PACK").is_ok_and(|value| value == "1");
    if reuse_disk_pack && disk_path.is_none() {
        vortex_bail!("TPCH_REUSE_DISK_PACK requires TPCH_DISK_PATH");
    }
    let disk_cache_mode = std::env::var("TPCH_CACHE_MODE").unwrap_or_else(|_| "cold".to_string());
    let evict_before_run = match disk_cache_mode.as_str() {
        "cold" => true,
        "hot" => false,
        mode => vortex_bail!("TPCH_CACHE_MODE must be `cold` or `hot`, got `{mode}`"),
    };
    let io_depth = std::env::var("TPCH_IO_DEPTH")
        .ok()
        .map(|value| {
            value
                .parse::<usize>()
                .map(|depth| depth.max(1))
                .map_err(|err| vortex_error::vortex_err!("invalid TPCH_IO_DEPTH: {err}"))
        })
        .transpose()?;
    let inline_max_bytes = std::env::var("TPCH_HOT_INLINE_MAX_BYTES")
        .ok()
        .map(|value| {
            value.parse::<usize>().map_err(|err| {
                vortex_error::vortex_err!("invalid TPCH_HOT_INLINE_MAX_BYTES: {err}")
            })
        })
        .transpose()?;
    let io_latency = std::env::var("TPCH_IO_LATENCY_US")
        .ok()
        .map(|value| {
            value
                .parse::<u64>()
                .map(Duration::from_micros)
                .map_err(|err| vortex_error::vortex_err!("invalid TPCH_IO_LATENCY_US: {err}"))
        })
        .transpose()?
        .unwrap_or_default();
    if inline_max_bytes.is_some() && evict_before_run {
        vortex_bail!("TPCH_HOT_INLINE_MAX_BYTES is only valid with TPCH_CACHE_MODE=hot");
    }
    if inline_max_bytes.is_some() && !io_latency.is_zero() {
        vortex_bail!("TPCH_HOT_INLINE_MAX_BYTES cannot bypass injected I/O latency");
    }
    let coalesce_override = match (
        std::env::var("TPCH_COALESCE_DISTANCE").ok(),
        std::env::var("TPCH_COALESCE_MAX_BYTES").ok(),
    ) {
        (None, None) => None,
        (distance, max_size) => {
            let defaults = CoalesceConfig::file();
            let distance = distance
                .map(|value| value.parse())
                .transpose()
                .map_err(|err| vortex_error::vortex_err!("invalid TPCH_COALESCE_DISTANCE: {err}"))?
                .unwrap_or(defaults.distance);
            let max_size = max_size
                .map(|value| value.parse())
                .transpose()
                .map_err(|err| vortex_error::vortex_err!("invalid TPCH_COALESCE_MAX_BYTES: {err}"))?
                .unwrap_or(defaults.max_size);
            Some(CoalesceConfig::new(distance, max_size))
        }
    };
    let backend = match disk_path.as_ref() {
        Some(path) => SegmentBackend::Disk(DiskBackend {
            path: path.clone(),
            specs: if reuse_disk_pack {
                reuse_segment_pack(path, &fixture.segment_buffers)?
            } else {
                write_segment_pack(path, &fixture.segment_buffers, evict_before_run)?
            },
            runtime: Handle::new(Arc::downgrade(&io_executor)),
            reused_pack: reuse_disk_pack,
            evict_before_run,
            coalesce_override,
            io_depth,
            inline_max_bytes,
            io_latency,
        }),
        None => SegmentBackend::Memory(Arc::clone(&segments)),
    };

    let splits = vortex_morsel_push::build_plan(
        &fixture.layout,
        &queries_probe(),
        None,
        ConjunctMode::Cascade,
    )
    .map(|plan| plan.natural_splits().len())
    .unwrap_or(0);
    println!(
        "lineitem SF={scale}: {} rows ({generated_rows} generated), {ncolumns} columns,          {splits} natural splits; generated in {}, written in {}",
        fixture.row_count,
        millis(gen_elapsed),
        millis(write_elapsed)
    );
    println!(
        "written through the btrblocks compressing pipeline (repartition {row_block} rows -> \
         coalesce {block_target}B -> compress -> buffer -> chunk -> flat); no zone maps, no dict \
         layout"
    );
    let mut segment_lengths: Vec<_> = fixture
        .segment_buffers
        .iter()
        .map(ByteBuffer::len)
        .collect();
    segment_lengths.sort_unstable();
    let segment_payload_bytes: usize = segment_lengths.iter().sum();
    let segment_min = segment_lengths.first().copied().unwrap_or(0);
    let segment_median = segment_lengths
        .get(segment_lengths.len() / 2)
        .copied()
        .unwrap_or(0);
    let segment_max = segment_lengths.last().copied().unwrap_or(0);
    println!(
        "segment payloads: {} segments, {segment_payload_bytes} bytes total, \
         {segment_min}/{segment_median}/{segment_max} bytes min/median/max",
        segment_lengths.len()
    );
    match disk_path {
        #[cfg(not(target_vendor = "apple"))]
        Some(path) if evict_before_run => println!(
            "host: {threads} available logical CPUs; file-backed segments at {}; cold cache: \
             POSIX_FADV_DONTNEED before every run; {iterations} alternating iterations, median \
             reported",
            path.display()
        ),
        #[cfg(target_vendor = "apple")]
        Some(path) if evict_before_run => println!(
            "host: {threads} available logical CPUs; file-backed segments at {}; uncached: \
             F_NOCACHE while writing and on every read; {iterations} alternating iterations, \
             median reported",
            path.display()
        ),
        Some(path) => println!(
            "host: {threads} available logical CPUs; file-backed segments at {}; hot cache: pages retained \
             after fixture write and correctness warm-up; {iterations} alternating iterations, \
             median reported",
            path.display()
        ),
        None => println!(
            "host: {threads} available logical CPUs; segments in memory; one untimed warm-up + \
             {iterations} grouped iterations per configuration, median reported"
        ),
    }
    if let SegmentBackend::Disk(disk) = &backend {
        if disk.reused_pack {
            println!("segment pack reuse: read-only validation; existing file was not rewritten");
        }
        println!(
            "physical I/O depth: {}; morsel I/O order: {}",
            disk.io_depth.unwrap_or(16),
            if std::env::var("VORTEX_MORSEL_IO_ROUND_ROBIN").is_ok_and(|value| value == "1") {
                "per-morsel round-robin"
            } else {
                "batch order"
            }
        );
        if let Some(max_bytes) = disk.inline_max_bytes {
            println!(
                "hot inline reads: synchronously probe submitted ranges up to {max_bytes} bytes"
            );
        }
        if !disk.io_latency.is_zero() {
            println!(
                "injected physical I/O latency: {} us per coalesced request",
                disk.io_latency.as_micros()
            );
        }
    }
    println!("both executors use workers prepared outside the timed interval");
    if let SegmentBackend::Disk(disk) = &backend
        && let Some(config) = disk.coalesce_override
    {
        println!(
            "file coalescing override: distance={} bytes, max={} bytes",
            config.distance, config.max_size
        );
    }
    println!();
    println!("schema: {}", fixture.layout.dtype());
    println!();

    let mut queries = tpch::lineitem_queries(fixture.layout.dtype())?;
    if let Ok(query) = std::env::var("TPCH_QUERY") {
        queries.retain(|candidate| candidate.name == query);
        if queries.is_empty() {
            vortex_bail!("TPCH_QUERY did not match a scan query: {query}");
        }
    }

    // Sweep mode: thread-scaling curves and a morsel-size sweep, to decompose *why* the
    // four-thread rows win rather than only reporting that they do.
    if std::env::var("TPCH_SWEEP").is_ok_and(|v| v == "1") {
        if matches!(&backend, SegmentBackend::Disk(_)) {
            vortex_bail!("TPCH_SWEEP is not supported with TPCH_DISK_PATH yet");
        }
        return sweep(
            &runtime, &session, &fixture, &segments, &queries, threads, iterations,
        );
    }

    // File-backed rows must not keep the generated in-memory segment payloads beside the file.
    // Preserve only the layout and pack specifications needed by the benchmark.
    drop(segments);
    if matches!(&backend, SegmentBackend::Disk(_)) {
        fixture.segment_buffers.clear();
        fixture.segments = Arc::new(TestSegments::default());
    }

    let selected_morsel_rows = std::env::var("TPCH_MORSEL_ROWS")
        .ok()
        .map(|value| parse_row_sizes("TPCH_MORSEL_ROWS", &value))
        .transpose()?
        .unwrap_or_else(|| vec![PRIMARY_MORSEL_ROWS]);
    let selected_lookahead = std::env::var("TPCH_LOOKAHEAD_MORSELS")
        .ok()
        .map(|value| {
            value
                .parse::<usize>()
                .map_err(|err| vortex_error::vortex_err!("invalid TPCH_LOOKAHEAD_MORSELS: {err}"))
        })
        .transpose()?
        .unwrap_or(0);
    let resident_morsels_per_thread = std::env::var("TPCH_RESIDENT_MORSELS_PER_THREAD")
        .ok()
        .map(|value| {
            value.parse::<usize>().map_err(|err| {
                vortex_error::vortex_err!("invalid TPCH_RESIDENT_MORSELS_PER_THREAD: {err}")
            })
        })
        .transpose()?
        .unwrap_or(1)
        .max(1);
    let selected_frontiers = std::env::var("TPCH_FRONTIERS_PER_THREAD")
        .ok()
        .map(|value| {
            value.parse::<usize>().map_err(|err| {
                vortex_error::vortex_err!("invalid TPCH_FRONTIERS_PER_THREAD: {err}")
            })
        })
        .transpose()?;
    let speculative_frontiers = std::env::var("TPCH_SPECULATIVE_FRONTIERS")
        .ok()
        .map(|value| {
            value.parse::<usize>().map_err(|err| {
                vortex_error::vortex_err!("invalid TPCH_SPECULATIVE_FRONTIERS: {err}")
            })
        })
        .transpose()?
        .unwrap_or(0);
    let adaptive_frontiers =
        std::env::var("TPCH_ADAPTIVE_FRONTIERS").is_ok_and(|value| value == "1");
    let frontier_refill_ranges = std::env::var("TPCH_FRONTIER_REFILL_RANGES")
        .ok()
        .map(|value| {
            value.parse::<usize>().map_err(|err| {
                vortex_error::vortex_err!("invalid TPCH_FRONTIER_REFILL_RANGES: {err}")
            })
        })
        .transpose()?
        .unwrap_or(32)
        .max(1);
    let morsel_only = std::env::var("TPCH_MORSEL_ONLY").is_ok_and(|value| value == "1")
        || std::env::var_os("TPCH_MORSEL_ROWS").is_some();
    let include_v1 = std::env::var("TPCH_INCLUDE_V1").is_ok_and(|value| value == "1");
    let frontier_matrix = std::env::var("TPCH_FRONTIER_MATRIX").is_ok_and(|value| value == "1");
    let frontier_refill_matrix =
        std::env::var("TPCH_FRONTIER_REFILL_MATRIX").is_ok_and(|value| value == "1");
    let frontier_policy_compare =
        std::env::var("TPCH_FRONTIER_POLICY_COMPARE").is_ok_and(|value| value == "1");
    let frontier_shape_compare =
        std::env::var("TPCH_FRONTIER_SHAPE_COMPARE").is_ok_and(|value| value == "1");
    let frontier_speculation_matrix =
        std::env::var("TPCH_FRONTIER_SPECULATION_MATRIX").is_ok_and(|value| value == "1");
    let frontier_down_matrix =
        std::env::var("TPCH_FRONTIER_DOWN_MATRIX").is_ok_and(|value| value == "1");
    let frontier_resident_matrix =
        std::env::var("TPCH_FRONTIER_RESIDENT_MATRIX").is_ok_and(|value| value == "1");
    let frontier_adaptive_compare =
        std::env::var("TPCH_FRONTIER_ADAPTIVE_COMPARE").is_ok_and(|value| value == "1");
    let configs = |threads: usize| {
        if frontier_adaptive_compare {
            let morsel_rows = selected_morsel_rows.first().copied().unwrap_or_default();
            let fixed = |speculative_frontiers| {
                Row::Morsel(MorselConfig {
                    threads,
                    morsel_rows,
                    resident_morsels_per_thread: 3,
                    frontier_lookahead_per_thread: Some(0),
                    speculative_frontiers,
                    frontier_refill_ranges,
                    ..Default::default()
                })
            };
            return vec![
                Row::V1Single,
                Row::V1Tokio(threads),
                fixed(2),
                fixed(3),
                Row::Morsel(MorselConfig {
                    threads,
                    morsel_rows,
                    resident_morsels_per_thread: 3,
                    frontier_lookahead_per_thread: Some(0),
                    adaptive_frontiers: true,
                    frontier_refill_ranges,
                    ..Default::default()
                }),
            ];
        }
        if frontier_speculation_matrix {
            let morsel_rows = selected_morsel_rows.first().copied().unwrap_or_default();
            let mut rows = vec![Row::V1Single, Row::V1Tokio(threads)];
            for speculative_frontiers in 0..=4 {
                rows.push(Row::Morsel(MorselConfig {
                    threads,
                    morsel_rows,
                    resident_morsels_per_thread: 3,
                    frontier_lookahead_per_thread: Some(0),
                    speculative_frontiers,
                    frontier_refill_ranges,
                    ..Default::default()
                }));
            }
            rows.push(Row::Morsel(MorselConfig {
                threads,
                morsel_rows,
                resident_morsels_per_thread: 3,
                frontier_lookahead_per_thread: Some(0),
                adaptive_frontiers: true,
                frontier_refill_ranges,
                ..Default::default()
            }));
            return rows;
        }
        if frontier_resident_matrix {
            let morsel_rows = selected_morsel_rows.first().copied().unwrap_or_default();
            let frontier_lookahead_per_thread = Some(selected_frontiers.unwrap_or(0));
            let mut rows = vec![Row::V1Single, Row::V1Tokio(threads)];
            rows.extend([1, 2, 3, 4, 6, 8, 12].map(|resident_morsels_per_thread| {
                Row::Morsel(MorselConfig {
                    threads,
                    morsel_rows,
                    resident_morsels_per_thread,
                    frontier_lookahead_per_thread,
                    speculative_frontiers,
                    frontier_refill_ranges,
                    ..Default::default()
                })
            }));
            return rows;
        }
        if frontier_down_matrix {
            let morsel_rows = selected_morsel_rows.first().copied().unwrap_or_default();
            let mut rows = vec![Row::V1Single, Row::V1Tokio(threads)];
            rows.extend([0, 2, 8, 24, 64].map(|frontier_lookahead_per_thread| {
                Row::Morsel(MorselConfig {
                    threads,
                    morsel_rows,
                    resident_morsels_per_thread,
                    frontier_lookahead_per_thread: Some(frontier_lookahead_per_thread),
                    speculative_frontiers,
                    adaptive_frontiers,
                    frontier_refill_ranges,
                    ..Default::default()
                })
            }));
            return rows;
        }
        if frontier_shape_compare {
            let morsel_rows = selected_morsel_rows.first().copied().unwrap_or_default();
            let frontier = |resident_morsels_per_thread, speculative_frontiers| {
                Row::Morsel(MorselConfig {
                    threads,
                    morsel_rows,
                    resident_morsels_per_thread,
                    frontier_lookahead_per_thread: Some(0),
                    speculative_frontiers,
                    frontier_refill_ranges,
                    ..Default::default()
                })
            };
            return vec![
                Row::V1Single,
                Row::V1Tokio(threads),
                frontier(1, 0),
                frontier(3, 0),
                frontier(3, 2),
            ];
        }
        if frontier_policy_compare {
            let morsel_rows = selected_morsel_rows.first().copied().unwrap_or_default();
            let frontier_lookahead_per_thread = Some(selected_frontiers.unwrap_or(0));
            return vec![
                Row::V1Single,
                Row::V1Tokio(threads),
                Row::Morsel(MorselConfig {
                    threads,
                    morsel_rows,
                    ..Default::default()
                }),
                Row::Morsel(MorselConfig {
                    threads,
                    morsel_rows,
                    resident_morsels_per_thread,
                    frontier_lookahead_per_thread,
                    speculative_frontiers,
                    frontier_refill_ranges: 1,
                    ..Default::default()
                }),
                Row::Morsel(MorselConfig {
                    threads,
                    morsel_rows,
                    resident_morsels_per_thread,
                    frontier_lookahead_per_thread,
                    speculative_frontiers,
                    frontier_refill_ranges,
                    ..Default::default()
                }),
            ];
        }
        if frontier_refill_matrix {
            let morsel_rows = selected_morsel_rows.first().copied().unwrap_or_default();
            let mut rows = vec![
                Row::V1Single,
                Row::V1Tokio(threads),
                Row::Morsel(MorselConfig {
                    threads,
                    morsel_rows,
                    ..Default::default()
                }),
            ];
            for (resident_morsels_per_thread, speculative_frontiers) in [(1, 0), (3, 2)] {
                for frontier_refill_ranges in [1, 2, 4, 8, 16, 32] {
                    rows.push(Row::Morsel(MorselConfig {
                        threads,
                        morsel_rows,
                        resident_morsels_per_thread,
                        frontier_lookahead_per_thread: Some(0),
                        speculative_frontiers,
                        frontier_refill_ranges,
                        ..Default::default()
                    }));
                }
            }
            return rows;
        }
        if frontier_matrix {
            let morsel_rows = selected_morsel_rows.first().copied().unwrap_or_default();
            let mut rows = vec![
                Row::V1Single,
                Row::V1Tokio(threads),
                Row::Morsel(MorselConfig {
                    threads,
                    morsel_rows,
                    ..Default::default()
                }),
            ];
            for resident_morsels_per_thread in 1..=3 {
                for speculative_frontiers in 0..=2 {
                    rows.push(Row::Morsel(MorselConfig {
                        threads,
                        morsel_rows,
                        resident_morsels_per_thread,
                        frontier_lookahead_per_thread: Some(0),
                        speculative_frontiers,
                        ..Default::default()
                    }));
                }
            }
            rows.extend([
                Row::Morsel(MorselConfig {
                    threads,
                    morsel_rows,
                    resident_morsels_per_thread: 3,
                    frontier_lookahead_per_thread: Some(1),
                    ..Default::default()
                }),
                Row::Morsel(MorselConfig {
                    threads,
                    morsel_rows,
                    resident_morsels_per_thread: 4,
                    frontier_lookahead_per_thread: Some(0),
                    ..Default::default()
                }),
            ]);
            return rows;
        }
        if morsel_only {
            let mut rows = Vec::new();
            if include_v1 {
                rows.extend([Row::V1Single, Row::V1Tokio(threads)]);
            }
            rows.extend(selected_morsel_rows.iter().copied().map(|morsel_rows| {
                Row::Morsel(MorselConfig {
                    threads,
                    morsel_rows,
                    lookahead_morsels: selected_lookahead,
                    resident_morsels_per_thread,
                    frontier_lookahead_per_thread: selected_frontiers.or(Some(0)),
                    speculative_frontiers,
                    adaptive_frontiers,
                    frontier_refill_ranges,
                    ..MorselConfig::frontier_defaults()
                })
            }));
            return rows;
        }
        vec![
            Row::V1Single,
            Row::V1Tokio(threads),
            Row::Morsel(MorselConfig {
                threads: 1,
                ..MorselConfig::frontier_defaults()
            }),
            Row::Morsel(MorselConfig {
                threads: 1,
                share_decodes: false,
                ..MorselConfig::frontier_defaults()
            }),
            Row::Morsel(MorselConfig {
                threads,
                ..MorselConfig::frontier_defaults()
            }),
            Row::Morsel(MorselConfig {
                threads,
                morsel_rows: PRIMARY_MORSEL_ROWS,
                ..MorselConfig::frontier_defaults()
            }),
        ]
    };

    if let Ok(memory_row) = std::env::var("TPCH_MEMORY_ROW") {
        if queries.len() != 1 {
            vortex_bail!("TPCH_MEMORY_ROW requires TPCH_QUERY to select exactly one query");
        }
        let row = match memory_row.as_str() {
            "v1-single" => Row::V1Single,
            "v1-tokio" => Row::V1Tokio(threads),
            "morsel" => Row::Morsel(MorselConfig {
                threads,
                morsel_rows: selected_morsel_rows[0],
                lookahead_morsels: selected_lookahead,
                resident_morsels_per_thread,
                frontier_lookahead_per_thread: selected_frontiers.or(Some(0)),
                speculative_frontiers,
                adaptive_frontiers,
                frontier_refill_ranges,
                ..MorselConfig::frontier_defaults()
            }),
            value => vortex_bail!(
                "TPCH_MEMORY_ROW must be `v1-single`, `v1-tokio`, or `morsel`, got `{value}`"
            ),
        };
        let query = &queries[0];
        let (outcome, baseline_rss, peak_rss) = measure_peak_rss(|| {
            run_once_discard(&runtime, &session, &fixture.layout, &backend, query, row)
        })?;
        println!("## Peak RSS — {} / {}", query.name, row.label());
        println!();
        println!("baseline RSS: {}", mib(baseline_rss));
        println!("peak RSS: {}", mib(peak_rss));
        println!(
            "incremental peak RSS: {}",
            mib(peak_rss.saturating_sub(baseline_rss))
        );
        println!("wall: {}", millis(outcome.wall));
        if let Some(stats) = outcome.stats {
            println!(
                "peak credited output arrays: {}",
                mib(stats.output_bytes_max)
            );
            println!("peak credited output rows: {}", stats.output_rows_max);
            println!(
                "raw I/O cells (end/peak): {}/{}",
                stats.io_cells_live, stats.io_cells_live_max
            );
            println!(
                "raw I/O bytes (end/peak): {}/{}",
                mib(stats.io_retained_bytes),
                mib(stats.io_retained_bytes_max)
            );
            println!("cancelled source futures: {}", stats.io_cancellations);
        }
        return Ok(());
    }

    for query in &queries {
        // Exactness first. Any disagreement aborts: on a real query over real data, a
        // configuration that does not reproduce V1's output exactly is a bug, not a table row.
        let oracle = run_once(
            &runtime,
            &session,
            &fixture.layout,
            &backend,
            query,
            Row::V1Single,
        )?;
        let dtype = query
            .projection
            .bind(fixture.layout.dtype())?
            .dtype()
            .clone();

        for row in configs(threads) {
            let outcome = run_once(&runtime, &session, &fixture.layout, &backend, query, row)?;
            if outcome.rows != oracle.rows {
                vortex_bail!(
                    "{} / {}: row count {} != V1's {}",
                    query.name,
                    row.label(),
                    outcome.rows,
                    oracle.rows
                );
            }
            assert_same_rows(&session, &dtype, &oracle, &outcome).map_err(|err| {
                err.with_context(format!("{} / {} exactness", query.name, row.label()))
            })?;
        }

        let validated = configs(threads);
        let mut samples: Vec<Vec<RunOutcome>> = validated.iter().map(|_| Vec::new()).collect();
        if matches!(&backend, SegmentBackend::Memory(_)) {
            for (idx, row) in validated.iter().enumerate() {
                // A serial configuration otherwise leaves most cores idle immediately before the
                // next parallel configuration. Warm and sample each in-memory executor as an
                // independent steady-state compute benchmark.
                drop(run_once_discard(
                    &runtime,
                    &session,
                    &fixture.layout,
                    &backend,
                    query,
                    *row,
                )?);
                for _ in 0..iterations {
                    let outcome = run_once_discard(
                        &runtime,
                        &session,
                        &fixture.layout,
                        &backend,
                        query,
                        *row,
                    )?;
                    samples[idx].push(outcome);
                }
            }
        } else {
            for _ in 0..iterations {
                for (idx, row) in validated.iter().enumerate() {
                    let outcome = run_once_discard(
                        &runtime,
                        &session,
                        &fixture.layout,
                        &backend,
                        query,
                        *row,
                    )?;
                    samples[idx].push(outcome);
                }
            }
        }

        let timings: Vec<Timing> = validated
            .iter()
            .zip(samples)
            .map(|(row, mut runs)| {
                runs.sort_by_key(|run| run.wall);
                let min = runs.first().map(|run| run.wall).unwrap_or_default();
                let max = runs.last().map(|run| run.wall).unwrap_or_default();
                let median = &runs[runs.len() / 2];
                Timing {
                    label: row.label(),
                    median: median.wall,
                    min,
                    max,
                    rows: median.rows,
                    ttfb: median.time_to_first_batch,
                    requests: median
                        .source_io_requests
                        .or_else(|| median.stats.as_ref().map(|s| s.io_requests)),
                    bytes: median
                        .source_io_bytes
                        .or_else(|| median.stats.as_ref().map(|s| s.io_bytes)),
                    segment_bytes: median.stats.as_ref().map(|s| s.io_bytes),
                    waits: median.stats.as_ref().map(|s| s.io_waits),
                    nowait_attempts: median
                        .source_nowait
                        .map(|(attempts, ..)| attempts)
                        .or_else(|| median.stats.as_ref().map(|s| s.nowait_attempts)),
                    nowait_hits: median
                        .source_nowait
                        .map(|(_, hits, ..)| hits)
                        .or_else(|| median.stats.as_ref().map(|s| s.nowait_hits)),
                    nowait_misses: median
                        .source_nowait
                        .map(|(_, _, misses, _)| misses)
                        .or_else(|| median.stats.as_ref().map(|s| s.nowait_misses)),
                    nowait_unsupported: median
                        .source_nowait
                        .map(|(_, _, _, unsupported)| unsupported)
                        .or_else(|| median.stats.as_ref().map(|s| s.nowait_unsupported)),
                    wait_time: median.stats.as_ref().map(|s| s.io_wait_time),
                    decodes: median.stats.as_ref().map(|s| s.decodes),
                    reuses: median.stats.as_ref().map(|s| s.decode_reuses),
                    morsels: median.stats.as_ref().map(|s| s.morsels),
                    push_transitions: median.stats.as_ref().map(|s| s.push_node_transitions),
                    push_inline_transfers: median.stats.as_ref().map(|s| s.push_inline_transfers),
                    push_dispatch_spills: median.stats.as_ref().map(|s| s.push_dispatch_spills),
                    push_fast_stage_transfers: median
                        .stats
                        .as_ref()
                        .map(|s| s.push_fast_stage_transfers),
                    push_cold_frame_spills: median.stats.as_ref().map(|s| s.push_cold_frame_spills),
                    push_runtime_mask_clones: median
                        .stats
                        .as_ref()
                        .map(|s| s.push_runtime_mask_clones),
                    io_uses: median.stats.as_ref().map(|s| s.io_uses),
                    logical_requests: median.stats.as_ref().map(|s| s.io_requests),
                    io_batches: median.stats.as_ref().map(|s| s.io_batches),
                    lookahead_refills: median.stats.as_ref().map(|s| s.lookahead_refills),
                    io_cells_live: median.stats.as_ref().map(|s| s.io_cells_live),
                    io_cells_live_max: median.stats.as_ref().map(|s| s.io_cells_live_max),
                    io_retained_bytes: median.stats.as_ref().map(|s| s.io_retained_bytes),
                    io_retained_bytes_max: median.stats.as_ref().map(|s| s.io_retained_bytes_max),
                    io_cancellations: median.stats.as_ref().map(|s| s.io_cancellations),
                    execute_io_blocks: median.stats.as_ref().map(|s| s.execute_io_blocks),
                    morsels_blocked_for_io: median.stats.as_ref().map(|s| s.morsels_blocked_for_io),
                    io_uses_per_morsel_min: median
                        .stats
                        .as_ref()
                        .and_then(|s| s.io_uses_per_morsel_min),
                    io_uses_per_morsel_max: median.stats.as_ref().map(|s| s.io_uses_per_morsel_max),
                    io_requests_per_morsel_min: median
                        .stats
                        .as_ref()
                        .and_then(|s| s.io_requests_per_morsel_min),
                    io_requests_per_morsel_max: median
                        .stats
                        .as_ref()
                        .map(|s| s.io_requests_per_morsel_max),
                    io_batches_per_morsel_min: median
                        .stats
                        .as_ref()
                        .and_then(|s| s.io_batches_per_morsel_min),
                    io_batches_per_morsel_max: median
                        .stats
                        .as_ref()
                        .map(|s| s.io_batches_per_morsel_max),
                    io_blocks_per_morsel_max: median
                        .stats
                        .as_ref()
                        .map(|s| s.io_blocks_per_morsel_max),
                    io_occupancy: median.source_io_occupancy,
                    io_oracle: median.stats.as_ref().and_then(|stats| {
                        (stats.io_oracle_learned_keys > 0 || stats.io_oracle_replay_keys > 0)
                            .then_some(IoOracleTiming {
                                learned_keys: stats.io_oracle_learned_keys,
                                replay_keys: stats.io_oracle_replay_keys,
                                replay_hits: stats.io_oracle_replay_hits,
                                replay_misses: stats.io_oracle_replay_misses,
                                reordered_reads: stats.io_oracle_reordered_reads,
                                reordered_batches: stats.io_oracle_reordered_batches,
                                start_inversions: stats.io_oracle_start_inversions,
                                start_pairs: stats.io_oracle_start_pairs,
                                completion_inversions: stats.io_oracle_completion_inversions,
                                completion_pairs: stats.io_oracle_completion_pairs,
                                unused_started: stats.io_oracle_unused_started,
                                first_need_ready: stats.io_oracle_first_need_ready,
                                first_need_requested: stats.io_oracle_first_need_requested,
                                first_need_unissued: stats.io_oracle_first_need_unissued,
                                late_read_time: stats.io_oracle_late_read_time,
                                late_read_time_max: stats.io_oracle_late_read_time_max,
                                ready_lead_time: stats.io_oracle_ready_lead_time,
                            })
                    }),
                    push_profile: median.stats.as_ref().map(|stats| PushProfileTiming {
                        runtime: stats.push_profile_runtime_time,
                        activation: stats.push_profile_activation_time,
                        root: stats.push_profile_root_time,
                        flat: stats.push_profile_flat,
                        flat_decode: stats.push_profile_flat_decode,
                        flat_filter: stats.push_profile_flat_filter,
                        chunked: stats.push_profile_chunked,
                        struct_: stats.push_profile_struct,
                        conjunct: stats.push_profile_conjunct,
                        filter: stats.push_profile_filter,
                        other: stats.push_profile_other,
                    }),
                }
            })
            .collect();

        report(query, &timings, fixture.row_count);
    }

    println!("Every configuration reproduced V1's dtype, row count and ordered content exactly.");
    drop(io_executor);
    Ok(())
}

/// A whole-row projection, used only to count the file's natural splits for the header line.
fn queries_probe() -> vortex_array::expr::Expression {
    vortex_array::expr::root()
}

fn parse_row_sizes(name: &str, value: &str) -> VortexResult<Vec<u64>> {
    let sizes: Vec<u64> = value
        .split(',')
        .map(str::trim)
        .map(|size| {
            size.parse::<u64>()
                .map_err(|err| vortex_error::vortex_err!("invalid {name} value `{size}`: {err}"))
        })
        .collect::<VortexResult<_>>()?;
    if sizes.is_empty() || sizes.contains(&0) {
        vortex_bail!("{name} must contain positive comma-separated row counts");
    }
    Ok(sizes)
}

/// Sweep worker counts relative to the process's available logical CPUs.
///
/// CPU affinity determines whether `available_cpus` represents physical cores, SMT siblings, or a
/// mixture. Record the host topology and affinity mask beside a sweep before interpreting a row as
/// one worker per physical core. V1 also spawns `concurrency` split tasks per runtime worker, while
/// the morsel driver has one affinity-owned active morsel per worker.
fn sweep(
    runtime: &tokio::runtime::Runtime,
    session: &VortexSession,
    fixture: &vortex_morsel_push::fixtures::Fixture,
    segments: &Arc<dyn SegmentSource>,
    queries: &[Query],
    available_cpus: usize,
    iterations: usize,
) -> VortexResult<()> {
    println!("## Driving threads vs available CPUs ({available_cpus} logical CPUs)");
    println!();
    println!(
        "Morsel driver: one affinity-owned active morsel per worker. Interpret \
         `x{available_cpus}` using the process affinity mask and host CPU topology."
    );
    println!();

    let thread_counts = [
        1usize,
        2,
        available_cpus,
        available_cpus * 2,
        available_cpus * 4,
    ];
    print!("| query |");
    for n in &thread_counts {
        print!(" D x{n} |");
    }
    println!(" best | vs D x{available_cpus} |");
    print!("|---|");
    for _ in 0..thread_counts.len() + 2 {
        print!("--:|");
    }
    println!();

    for query in queries {
        let mut walls = Vec::new();
        for &n in &thread_counts {
            walls.push(median(iterations, || {
                run_morsel(
                    session,
                    &fixture.layout,
                    segments,
                    query,
                    MorselConfig {
                        threads: n,
                        ..MorselConfig::frontier_defaults()
                    },
                )
            })?);
        }
        let at_available_cpus = walls[2];
        let best = walls
            .iter()
            .enumerate()
            .min_by_key(|(_, w)| **w)
            .map(|(idx, w)| (thread_counts[idx], *w))
            .unwrap_or((available_cpus, at_available_cpus));
        print!("| {} |", query.name);
        for wall in &walls {
            print!(" {} |", millis(*wall));
        }
        println!(
            " x{} | {:.2}x |",
            best.0,
            best.1.as_secs_f64() / at_available_cpus.as_secs_f64()
        );
    }
    println!();

    println!("## V1 concurrent units: {available_cpus} workers x per-worker split concurrency");
    println!();
    println!(
        "V1's parallelism is workers x concurrency. This sweeps the second factor to check the \
         baseline is not simply mis-tuned."
    );
    println!();
    print!("| query | V1 x1 |");
    for c in [1usize, 2, 4, 8, 16] {
        print!(" tok{available_cpus} c={c} |");
    }
    println!(" best |");
    print!("|---|--:|");
    for _ in 0..6 {
        print!("--:|");
    }
    println!();

    for query in queries {
        let single = median(iterations, || {
            run_v1(session, &fixture.layout, segments, query)
        })?;
        let mut walls = Vec::new();
        for c in [1usize, 2, 4, 8, 16] {
            walls.push(median(iterations, || {
                run_v1_tokio_with(runtime, session, &fixture.layout, segments, query, Some(c))
            })?);
        }
        let best = walls.iter().copied().min().unwrap_or(single);
        print!("| {} | {} |", query.name, millis(single));
        for wall in &walls {
            print!(" {} |", millis(*wall));
        }
        println!(" {} |", millis(best));
    }
    println!();

    println!("## Morsel size at {available_cpus} threads");
    println!();
    println!("| query | morsels@splits | splits | 16k | 128k | 256k | 1M |");
    println!("|---|--:|--:|--:|--:|--:|--:|");
    for query in queries {
        let mut cells = Vec::new();
        let mut morsel_count = 0;
        for size in [0u64, 16_384, PRIMARY_MORSEL_ROWS, 262_144, 1_048_576] {
            let config = MorselConfig {
                threads: available_cpus,
                morsel_rows: size,
                ..MorselConfig::frontier_defaults()
            };
            if size == 0 {
                morsel_count = run_morsel(session, &fixture.layout, segments, query, config)?
                    .stats
                    .as_ref()
                    .map(|s| s.morsels)
                    .unwrap_or(0);
            }
            let wall = median(iterations, || {
                run_morsel(session, &fixture.layout, segments, query, config)
            })?;
            cells.push(millis(wall));
        }
        println!(
            "| {} | {} | {} |",
            query.name,
            morsel_count,
            cells.join(" | ")
        );
    }
    println!();
    Ok(())
}

fn measure_peak_rss(
    run: impl FnOnce() -> VortexResult<RunOutcome>,
) -> VortexResult<(RunOutcome, u64, u64)> {
    let running = Arc::new(AtomicBool::new(true));
    let sampler_running = Arc::clone(&running);
    let (baseline_tx, baseline_rx) = sync_channel(1);
    let sampler = thread::spawn(move || {
        let pid = Pid::from_u32(std::process::id());
        let mut system = System::new_with_specifics(
            RefreshKind::nothing().with_processes(ProcessRefreshKind::nothing().with_memory()),
        );
        let refresh = |system: &mut System| {
            system.refresh_processes(ProcessesToUpdate::Some(&[pid]), true);
            system
                .process(pid)
                .map(|process| process.memory())
                .unwrap_or(0)
        };
        let baseline = refresh(&mut system);
        let _ = baseline_tx.send(baseline);
        let mut peak = baseline;
        while sampler_running.load(Ordering::Acquire) {
            peak = peak.max(refresh(&mut system));
            thread::sleep(Duration::from_millis(1));
        }
        peak.max(refresh(&mut system))
    });
    let baseline = baseline_rx
        .recv()
        .map_err(|err| vortex_error::vortex_err!("RSS sampler failed to start: {err}"))?;
    let outcome = run();
    running.store(false, Ordering::Release);
    let peak = sampler
        .join()
        .map_err(|_| vortex_error::vortex_err!("RSS sampler panicked"))?;
    Ok((outcome?, baseline, peak))
}

fn mib(bytes: u64) -> String {
    format!("{:.1} MiB", bytes as f64 / (1024.0 * 1024.0))
}

fn median(
    iterations: usize,
    mut run: impl FnMut() -> VortexResult<RunOutcome>,
) -> VortexResult<Duration> {
    let mut walls = Vec::with_capacity(iterations);
    for _ in 0..iterations {
        walls.push(run()?.wall);
    }
    walls.sort_unstable();
    Ok(walls[walls.len() / 2])
}

fn run_once(
    runtime: &tokio::runtime::Runtime,
    session: &VortexSession,
    layout: &LayoutRef,
    backend: &SegmentBackend,
    query: &Query,
    row: Row,
) -> VortexResult<RunOutcome> {
    run_once_with_output(runtime, session, layout, backend, query, row, true)
}

fn run_once_discard(
    runtime: &tokio::runtime::Runtime,
    session: &VortexSession,
    layout: &LayoutRef,
    backend: &SegmentBackend,
    query: &Query,
    row: Row,
) -> VortexResult<RunOutcome> {
    run_once_with_output(runtime, session, layout, backend, query, row, false)
}

fn run_once_with_output(
    runtime: &tokio::runtime::Runtime,
    session: &VortexSession,
    layout: &LayoutRef,
    backend: &SegmentBackend,
    query: &Query,
    row: Row,
    retain_output: bool,
) -> VortexResult<RunOutcome> {
    let run_session = match backend {
        SegmentBackend::Memory(_) => session.clone(),
        SegmentBackend::Disk(disk) => session.clone().with_handle(disk.runtime.clone()),
    };
    let (segments, counters) = backend.source(&run_session)?;

    let mut outcome = match (row, retain_output) {
        (Row::V1Single, true) => run_v1(&run_session, layout, &segments, query),
        (Row::V1Single, false) => run_v1_discard(&run_session, layout, &segments, query),
        (Row::V1Tokio(_), true) => run_v1_tokio(runtime, &run_session, layout, &segments, query),
        (Row::V1Tokio(_), false) => {
            run_v1_tokio_discard(runtime, &run_session, layout, &segments, query)
        }
        (Row::Morsel(config), true) => run_morsel(&run_session, layout, &segments, query, config),
        (Row::Morsel(config), false) => {
            run_morsel_discard(&run_session, layout, &segments, query, config)
        }
    }?;
    if let Some(counters) = counters {
        outcome.source_io_requests = Some(counters.ranges.load(Ordering::Relaxed));
        outcome.source_io_bytes = Some(counters.bytes.load(Ordering::Relaxed));
        let nowait_attempts = counters.nowait_attempts.load(Ordering::Relaxed);
        if nowait_attempts > 0 {
            outcome.source_nowait = Some((
                nowait_attempts,
                counters.nowait_hits.load(Ordering::Relaxed),
                counters.nowait_misses.load(Ordering::Relaxed),
                counters.nowait_unsupported.load(Ordering::Relaxed),
            ));
        }
        outcome.source_io_occupancy = Some(counters.occupancy());
    }
    Ok(outcome)
}

fn report(query: &Query, timings: &[Timing], total_rows: u64) {
    let baseline = timings
        .iter()
        .find(|t| t.label.starts_with("A  "))
        .map(|t| t.median)
        .unwrap_or_default();
    let selectivity = timings
        .first()
        .map(|t| t.rows as f64 / total_rows.max(1) as f64 * 100.0)
        .unwrap_or(0.0);

    println!(
        "### {} — {} rows out ({:.2}% selectivity)",
        query.name,
        timings.first().map(|t| t.rows).unwrap_or(0),
        selectivity
    );
    println!();
    println!(
        "| executor | wall | vs V1 | ttfb | morsels | push transitions/inline/spill | named IO/morsel | new requests/morsel | IO \
         batches/morsel | blocked/morsel | physical reads | physical bytes | segment bytes | \
         fast/cold/mask-clones | nowait hit/miss/unsupported | pending polls | async wait | decodes | reuses |"
    );
    println!("|---|--:|--:|--:|--:|--:|--:|--:|--:|--:|--:|--:|--:|--:|--:|--:|--:|--:|--:|");
    for timing in timings {
        let ratio = if baseline.is_zero() {
            "—".to_string()
        } else {
            format!(
                "{:.2}x",
                timing.median.as_secs_f64() / baseline.as_secs_f64()
            )
        };
        println!(
            "| {} | {} | {} | {} | {} | {} | {} | {} | {} | {} | {} | {} | {} | {} | {} | {} | {} | {} | {} |",
            timing.label,
            timing_range(timing.median, timing.min, timing.max),
            ratio,
            timing.ttfb.map(millis).unwrap_or_else(|| "—".to_string()),
            opt(timing.morsels),
            push_pipeline(timing),
            per_morsel(
                timing.io_uses,
                timing.morsels,
                timing.io_uses_per_morsel_min,
                timing.io_uses_per_morsel_max,
            ),
            per_morsel(
                timing.logical_requests,
                timing.morsels,
                timing.io_requests_per_morsel_min,
                timing.io_requests_per_morsel_max,
            ),
            per_morsel(
                timing.io_batches,
                timing.morsels,
                timing.io_batches_per_morsel_min,
                timing.io_batches_per_morsel_max,
            ),
            blocked_per_morsel(
                timing.execute_io_blocks,
                timing.morsels,
                timing.morsels_blocked_for_io,
                timing.io_blocks_per_morsel_max,
            ),
            opt(timing.requests),
            opt(timing.bytes),
            opt(timing.segment_bytes),
            push_fast_path(timing),
            nowait(timing),
            opt(timing.waits),
            timing
                .wait_time
                .map(millis)
                .unwrap_or_else(|| "—".to_string()),
            opt(timing.decodes),
            opt(timing.reuses),
        );
    }
    println!();
    report_io_occupancy(timings);
    report_refill_metrics(timings);
    report_retention_metrics(timings);
    report_io_oracle(timings);
    report_push_profile(timings);
}

fn report_retention_metrics(timings: &[Timing]) {
    if !timings
        .iter()
        .any(|timing| timing.io_cells_live_max.is_some())
    {
        return;
    }
    println!("| executor | raw cells end/peak | raw bytes end/peak | cancelled source futures |");
    println!("|---|--:|--:|--:|");
    for timing in timings {
        let cells = timing
            .io_cells_live
            .zip(timing.io_cells_live_max)
            .map(|(end, peak)| format!("{end}/{peak}"))
            .unwrap_or_else(|| "—".to_string());
        let bytes = timing
            .io_retained_bytes
            .zip(timing.io_retained_bytes_max)
            .map(|(end, peak)| format!("{}/{}", mib(end), mib(peak)))
            .unwrap_or_else(|| "—".to_string());
        println!(
            "| {} | {} | {} | {} |",
            timing.label,
            cells,
            bytes,
            opt(timing.io_cancellations)
        );
    }
    println!();
}

fn report_refill_metrics(timings: &[Timing]) {
    if !timings
        .iter()
        .any(|timing| timing.lookahead_refills.is_some())
    {
        return;
    }
    println!("| executor | lookahead refills | IO start batches | average physical read |");
    println!("|---|--:|--:|--:|");
    for timing in timings {
        let average = timing
            .bytes
            .zip(timing.requests)
            .filter(|(_, requests)| *requests > 0)
            .map(|(bytes, requests)| format!("{:.1} KiB", bytes as f64 / requests as f64 / 1024.0))
            .unwrap_or_else(|| "—".to_string());
        println!(
            "| {} | {} | {} | {} |",
            timing.label,
            opt(timing.lookahead_refills),
            opt(timing.io_batches),
            average
        );
    }
    println!();
}

fn report_io_occupancy(timings: &[Timing]) {
    if !timings.iter().any(|timing| timing.io_occupancy.is_some()) {
        return;
    }
    println!(
        "| executor | physical depth/max | physical I/O span | full | underfilled busy | idle gap | not full | refill wait | final drain | slot utilization |"
    );
    println!("|---|--:|--:|--:|--:|--:|--:|--:|--:|--:|");
    for timing in timings {
        let Some(occupancy) = timing.io_occupancy else {
            continue;
        };
        let not_full = occupancy.underfilled + occupancy.idle;
        let slot_capacity_nanos = occupancy
            .span
            .as_nanos()
            .saturating_mul(occupancy.capacity as u128);
        let slot_utilization = if slot_capacity_nanos == 0 {
            "—".to_string()
        } else {
            format!(
                "{:.1}%",
                occupancy.active_slot_nanos as f64 / slot_capacity_nanos as f64 * 100.0
            )
        };
        println!(
            "| {} | {}/{} | {} | {} | {} | {} | {} | {} | {} | {} |",
            timing.label,
            occupancy.capacity,
            occupancy.max_active,
            millis(occupancy.span),
            duration_share(occupancy.full, occupancy.span),
            duration_share(occupancy.underfilled, occupancy.span),
            duration_share(occupancy.idle, occupancy.span),
            duration_share(not_full, occupancy.span),
            duration_share(occupancy.refill_wait, occupancy.span),
            duration_share(occupancy.tail_drain, occupancy.span),
            slot_utilization,
        );
    }
    println!();
}

fn duration_share(value: Duration, total: Duration) -> String {
    if total.is_zero() {
        return "—".to_string();
    }
    format!(
        "{} ({:.1}%)",
        millis(value),
        value.as_secs_f64() / total.as_secs_f64() * 100.0
    )
}

fn report_io_oracle(timings: &[Timing]) {
    if !timings.iter().any(|timing| timing.io_oracle.is_some()) {
        return;
    }
    println!(
        "| executor | learned | replay keys | replay hit/miss | reordered positions/batches | \
         submit wrong pairs/batch | completion wrong pairs/batch | first need ready/in-flight/unissued | \
         late total/max | ready lead total | unused starts |"
    );
    println!("|---|--:|--:|--:|--:|--:|--:|--:|--:|--:|--:|");
    for timing in timings {
        let Some(oracle) = &timing.io_oracle else {
            continue;
        };
        println!(
            "| {} | {} | {} | {}/{} | {}/{} | {} | {} | {}/{}/{} | {}/{} | {} | {} |",
            timing.label,
            oracle.learned_keys,
            oracle.replay_keys,
            oracle.replay_hits,
            oracle.replay_misses,
            oracle.reordered_reads,
            oracle.reordered_batches,
            inversion_rate(oracle.start_inversions, oracle.start_pairs),
            inversion_rate(oracle.completion_inversions, oracle.completion_pairs),
            oracle.first_need_ready,
            oracle.first_need_requested,
            oracle.first_need_unissued,
            millis(oracle.late_read_time),
            millis(oracle.late_read_time_max),
            millis(oracle.ready_lead_time),
            oracle.unused_started,
        );
    }
    println!();
}

fn inversion_rate(inversions: u64, pairs: u64) -> String {
    if pairs == 0 {
        return "—".to_string();
    }
    format!(
        "{:.2}% ({inversions}/{pairs})",
        inversions as f64 / pairs as f64 * 100.0
    )
}

fn report_push_profile(timings: &[Timing]) {
    if !timings.iter().any(|timing| {
        timing
            .push_profile
            .as_ref()
            .is_some_and(|profile| !profile.runtime.is_zero())
    }) {
        return;
    }
    println!(
        "| executor | runtime CPU | node CPU | protocol CPU | activation | root | Flat | decode⊂Flat | filter⊂Flat | Chunked | Struct | Conjunct | Filter | other |"
    );
    println!("|---|--:|--:|--:|--:|--:|--:|--:|--:|--:|--:|--:|--:|--:|");
    for timing in timings {
        let Some(profile) = timing.push_profile.as_ref() else {
            continue;
        };
        if profile.runtime.is_zero() {
            continue;
        }
        let node_time = profile.flat.1
            + profile.chunked.1
            + profile.struct_.1
            + profile.conjunct.1
            + profile.filter.1
            + profile.other.1;
        println!(
            "| {} | {} | {} | {} | {} | {} | {} | {} | {} | {} | {} | {} | {} | {} |",
            timing.label,
            millis(profile.runtime),
            millis(node_time),
            millis(profile.runtime.saturating_sub(node_time)),
            millis(profile.activation),
            millis(profile.root),
            profile_cell(profile.flat),
            profile_cell(profile.flat_decode),
            profile_cell(profile.flat_filter),
            profile_cell(profile.chunked),
            profile_cell(profile.struct_),
            profile_cell(profile.conjunct),
            profile_cell(profile.filter),
            profile_cell(profile.other),
        );
    }
    println!();
}

fn profile_cell((calls, elapsed): (u64, Duration)) -> String {
    format!("{calls}/{}", millis(elapsed))
}

fn push_pipeline(timing: &Timing) -> String {
    match (
        timing.push_transitions,
        timing.push_inline_transfers,
        timing.push_dispatch_spills,
    ) {
        (Some(transitions), Some(inline), Some(spills)) => {
            format!("{transitions}/{inline}/{spills}")
        }
        _ => "—".to_string(),
    }
}

fn push_fast_path(timing: &Timing) -> String {
    match (
        timing.push_fast_stage_transfers,
        timing.push_cold_frame_spills,
        timing.push_runtime_mask_clones,
    ) {
        (Some(fast), Some(cold), Some(mask_clones)) => format!("{fast}/{cold}/{mask_clones}"),
        _ => "—".to_string(),
    }
}

fn nowait(timing: &Timing) -> String {
    match (
        timing.nowait_attempts,
        timing.nowait_hits,
        timing.nowait_misses,
        timing.nowait_unsupported,
    ) {
        (Some(0), ..) | (None, ..) => "—".to_string(),
        (Some(_), Some(hits), Some(misses), Some(unsupported)) => {
            format!("{hits}/{misses}/{unsupported}")
        }
        _ => "—".to_string(),
    }
}

fn millis(duration: Duration) -> String {
    format!("{:.3}ms", duration.as_secs_f64() * 1000.0)
}

fn timing_range(median: Duration, min: Duration, max: Duration) -> String {
    format!("{} [{},{}]", millis(median), millis(min), millis(max))
}

fn opt(value: Option<u64>) -> String {
    value.map(|v| v.to_string()).unwrap_or_else(|| "—".into())
}

fn per_morsel(
    total: Option<u64>,
    morsels: Option<u64>,
    min: Option<u64>,
    max: Option<u64>,
) -> String {
    match (total, morsels, min, max) {
        (Some(total), Some(morsels), Some(min), Some(max)) if morsels > 0 => {
            format!("{:.2} [{min},{max}]", total as f64 / morsels as f64)
        }
        _ => "—".to_string(),
    }
}

fn blocked_per_morsel(
    total: Option<u64>,
    morsels: Option<u64>,
    blocked_morsels: Option<u64>,
    max: Option<u64>,
) -> String {
    match (total, morsels, blocked_morsels, max) {
        (Some(total), Some(morsels), Some(blocked), Some(max)) if morsels > 0 => format!(
            "{:.2} ({blocked}/{morsels}, max {max})",
            total as f64 / morsels as f64
        ),
        _ => "—".to_string(),
    }
}
